"use strict";
/* Inhalte wörtlich aus „Dein Strick-Adventskalender zum Mitstricken“ (Munich Publishing), ausgelesen aus Strick_Adventskalender_FINAL_v5.pdf. Nicht umformulieren. */
window.STRICK_INHALT = {"tueren":[{"nr":1,"titel":"Eine rechte Masche stricken","seite":9,"einleitung":["Eine rechte Masche besteht aus vier kleinen Bewegungen. Heute kannst du jede davon einzeln betrachten, bevor sie wieder zu einem vertrauten Ablauf wird."],"imBlick":"Die neue Schlinge nach vorn holen","bereit":["Schlage 12 Maschen in deiner vertrauten Anschlagart an. Halte die volle Nadel links, die leere rechts. Der Arbeitsfaden läuft über den linken Zeigefinger und liegt hinter der Arbeit."],"fotoEntdecken":{"src":"assets/fotos/t01-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t01-schritt-1.webp","w":616,"h":409,"alt":"Faden hinter der Arbeit"},{"src":"assets/fotos/t01-schritt-2.webp","w":616,"h":409,"alt":"Die Schlinge auf dem Schaft"}],"fotosDetail":[{"src":"assets/fotos/t01-detail-1.webp","w":616,"h":409,"alt":"Eine neue Masche auf der rechten Nadel"},{"src":"assets/fotos/t01-detail-2.webp","w":616,"h":409,"alt":"Die V-Form im Gestrick"}],"schritte":[{"nr":1,"titel":"In die Masche einstechen","text":["Führe die rechte Nadel von vorn nach hinten durch das vordere Maschenglied der ersten Masche: von links unten nach rechts oben. Die alte Masche bleibt auf der linken Nadel."]},{"nr":2,"titel":"Den Arbeitsfaden erfassen","text":["Lege den Arbeitsfaden gegen den Uhrzeigersinn um die rechte Nadel: Stelle dir dafür den Blick direkt auf ihre Spitze entlang des Schafts vor. Der Faden liegt hinter der Arbeit; die alte Masche bleibt links."]},{"nr":3,"titel":"Die neue Schlinge durchholen","text":["Ziehe die rechte Spitze mit dem erfassten Faden durch die alte Masche nach vorn zurück. So entsteht eine neue Schlinge auf der rechten Nadel. Teile dabei keine Garnfasern."]},{"nr":4,"titel":"Die alte Masche lösen","text":["Lass erst jetzt die alte Masche von der linken Spitze gleiten. Die neue bleibt rechts. Schiebe sie auf den gleichmäßig dicken Nadelschaft und lege den Faden nur leicht an."]}],"fotoErgebnis":{"src":"assets/fotos/t01-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Stricke alle 12 Maschen rechts. Wende: Die volle Nadel kommt wieder in die linke Hand. Lege den Faden nach hinten und stricke auch die Rückreihe rechts. Arbeite insgesamt vier Reihen. Die erste und letzte Masche werden ebenfalls rechts gestrickt."],"erkennen":["Du hast nach jeder Reihe weiterhin 12 Maschen. Rechte Maschen auf beiden Seiten ergeben kraus rechtes Gestrick mit Querrippen. Vier gestrickte Reihen bilden zwei Krausrippen; direkt an der Anschlagkante ist die Struktur noch weniger deutlich."],"hakt":[{"problem":"Die Nadel geht schwer hindurch.","loesung":"Schiebe die nächste Masche näher zur Spitze und entspanne den Faden. Stich durch die ganze Schlinge, ohne einzelne Fasern zu teilen."},{"problem":"Die neue Masche ist sehr eng.","loesung":"Bilde sie auf dem Nadelschaft und ziehe nach dem Abgleiten nur sanft nach. Sie soll sich noch verschieben lassen."}],"fuerHeute":["Lass das Stück auf der Nadel. Für Türchen 2 kannst du direkt damit weiterarbeiten."]},{"nr":2,"titel":"Eine linke Masche stricken","seite":14,"einleitung":["Die linke Masche ergänzt die rechte. Heute übst du vor allem, den Faden vor der Arbeit zu führen."],"imBlick":"Die Schlinge nach hinten holen","bereit":["Nimm ein kleines Übungsstück mit 12 Maschen auf der Nadel. Du brauchst nur dein Garn und die passenden Nadeln. Die Fadenhaltung ist dieselbe wie in Türchen 1."],"fotoEntdecken":{"src":"assets/fotos/t02-entdecken.webp","w":754,"h":334,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t02-schritt-1.webp","w":509,"h":226,"alt":"Faden vor der Arbeit"},{"src":"assets/fotos/t02-schritt-2.webp","w":509,"h":226,"alt":"Der Querbogen einer linken Masche"}],"fotosDetail":[{"src":"assets/fotos/t02-detail-1.webp","w":509,"h":226,"alt":"Den Faden über dem Zeigefinger führen"},{"src":"assets/fotos/t02-detail-2.webp","w":509,"h":226,"alt":"Die Schlinge auf dem Nadelschaft"}],"schritte":[{"nr":1,"titel":"Vorn bereitmachen","text":["Lege den Arbeitsfaden vor die Arbeit. Führe die rechte Nadel von rechts nach links durch das vordere Maschenglied der ersten Masche. Die alte Masche bleibt auf der linken Nadel."]},{"nr":2,"titel":"Den Faden umlegen","text":["Lege den Faden von oben um die rechte Nadel, gegen den Uhrzeigersinn bei einem gedachten Blick direkt auf ihre Spitze entlang des Schafts. Halte ihn leicht gespannt. Die alte Masche bleibt auf der linken Nadel."]},{"nr":3,"titel":"Die neue Schlinge holen","text":["Führe die rechte Nadelspitze mit dem erfassten Faden durch die alte Masche nach hinten. Auf der rechten Nadel entsteht die neue Schlinge. Stich dabei nicht in einzelne Garnfasern."]},{"nr":4,"titel":"Die alte Masche lösen","text":["Lass die alte Masche von der linken Nadel gleiten. Die neue Masche bleibt auf der rechten Nadel. Für die nächste linke Masche bleibt der Arbeitsfaden vor der Arbeit."]}],"fotoErgebnis":{"src":"assets/fotos/t02-ergebnis.webp","w":754,"h":334,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Stricke eine ganze Reihe mit linken Maschen. Wende die Arbeit und stricke die Rückreihe rechts. Wiederhole diese beiden Reihen noch einmal. So entstehen vier neue Reihen, bei denen du die Fadenlage bewusst wechselst."],"erkennen":["Nach jeder Reihe hast du weiterhin 12 Maschen. Durch den Wechsel aus einer linken und einer rechten Reihe entsteht glatt rechtes Gestrick. Eine Seite zeigt V-Maschen, die andere Querbögen. Hier beginnst du auf der Seite mit den linken Maschen."],"hakt":[{"problem":"Die Masche sitzt fest.","loesung":"Schiebe sie näher zur linken Spitze. Halte den Faden weniger straff und lass der neuen Schlinge auf der rechten Nadel etwas Raum."},{"problem":"Der Faden ist hinten.","loesung":"Lege ihn zwischen den Nadelspitzen nach vorn, bevor du wieder einstichst. Führe ihn dabei nicht zusätzlich über den Nadelschaft."}],"fuerHeute":["Lege das Stück einmal von beiden Seiten vor dich. Rechte und linke Maschen gehören zusammen: Was auf der einen Seite wie ein V aussieht, erscheint auf der anderen als Querbogen."]},{"nr":3,"titel":"Den Faden richtig wechseln","seite":19,"einleitung":["Beim Wechsel zwischen rechten und linken Maschen zieht der Arbeitsfaden mit um. Sein Weg entscheidet darüber, ob ungewollt eine neue Schlinge entsteht."],"imBlick":"Zwischen den Spitzen hindurch","bereit":["Schlage 12 Maschen an oder nimm ein kleines Stück mit 12 Maschen. Du übst einen Wechsel aus einer rechten und einer linken Masche. Es sind keine zusätzlichen Randmaschen vorgesehen."],"fotoEntdecken":{"src":"assets/fotos/t03-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t03-schritt-1.webp","w":616,"h":409,"alt":"Die Nadeln leicht auseinanderhalten"},{"src":"assets/fotos/t03-schritt-2.webp","w":616,"h":409,"alt":"Der Weg zwischen den Spitzen"}],"fotosDetail":[{"src":"assets/fotos/t03-detail-1.webp","w":616,"h":409,"alt":"Die Fadenlage beim Wechsel prüfen"},{"src":"assets/fotos/t03-detail-2.webp","w":616,"h":409,"alt":"Ohne zusätzlichen Umschlag weiterarbeiten"}],"schritte":[{"nr":1,"titel":"Mit einer rechten Masche beginnen","text":["Stricke die erste Masche rechts. Der Arbeitsfaden liegt hinter der Arbeit. Halte die Spitzen einen kleinen Abstand auseinander."]},{"nr":2,"titel":"Den Faden nach vorn führen","text":["Führe den Arbeitsfaden zwischen den beiden Nadelspitzen nach vorn. Er läuft durch die Lücke und wird nicht um die rechte Nadel geschlungen."]},{"nr":3,"titel":"Eine linke Masche stricken","text":["Stricke die nächste Masche links, wie in Türchen 2 gezeigt. Der Faden liegt dabei vor der Arbeit. Ziehe die fertige Masche nicht fest."]},{"nr":4,"titel":"Den Faden zurückführen","text":["Führe den Arbeitsfaden zwischen den Nadelspitzen wieder nach hinten. Jetzt ist die nächste rechte Masche an der Reihe. Wiederhole diesen Wechsel bis zum Reihenende."]}],"fotoErgebnis":{"src":"assets/fotos/t03-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Stricke vier Reihen. In jeder Reihe wiederholst du sechsmal: eine Masche rechts, eine Masche links. Wende jeweils am Reihenende. Bei 12 Maschen geht die Folge genau auf; die letzte Masche jeder Reihe ist links."],"erkennen":["Die Zahl bleibt bei 12. Es entstehen schmale Rippen aus rechten und linken Maschen. Das Stück kann sich in der Breite zusammenziehen. Zwischen zwei Maschen sollte keine lose zusätzliche Schlinge auf der Nadel liegen."],"hakt":[{"problem":"Eine zusätzliche Schlinge erscheint.","loesung":"Wahrscheinlich ist der Faden über die Nadel statt zwischen den Spitzen gewandert. Halte an und prüfe den letzten Wechsel, bevor du die Schlinge als Masche weiterstrickst."},{"problem":"Der Übergang wird locker.","loesung":"Führe den Faden dicht an den Spitzen entlang. Nach der nächsten Masche kannst du ihn sanft anlegen, ohne das Gestrick zusammenzuziehen."}],"fuerHeute":["Der wichtigste Weg heute ist sehr kurz: durch die Lücke zwischen den Spitzen. Wenn du ihn im Blick behältst, wird der Wechsel bald selbstverständlich."]},{"nr":4,"titel":"Maschen im Gestrick lesen","seite":24,"einleitung":["Ein Blick auf die Masche kann dir zeigen, was als Nächstes gestrickt werden soll. Heute bleiben die Nadeln zwischendurch einfach liegen."],"imBlick":"Die andere Seite erkennen","bereit":["Bereite ein kleines glatt rechtes Stück vor: 12 Maschen anschlagen, eine Reihe rechts und eine Reihe links im Wechsel stricken, insgesamt acht Reihen. Lass die Maschen auf der Nadel."],"fotoEntdecken":{"src":"assets/fotos/t04-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t04-schritt-1.webp","w":616,"h":409,"alt":"V-Spalten auf der Vorderseite"},{"src":"assets/fotos/t04-schritt-2.webp","w":616,"h":409,"alt":"Die beiden Schenkel einer Masche"}],"fotosDetail":[{"src":"assets/fotos/t04-detail-1.webp","w":616,"h":409,"alt":"Querbögen erkennen"},{"src":"assets/fotos/t04-detail-2.webp","w":616,"h":409,"alt":"Die linke Maschenerscheinung im Detail"}],"schritte":[{"nr":1,"titel":"Die Vorderseite ansehen","text":["Lege das Stück mit der glatten Seite zu dir. Die Maschen bilden senkrechte Spalten. In jeder Spalte liegt ein kleines V über dem nächsten."]},{"nr":2,"titel":"Ein ganzes V verfolgen","text":["Zeige mit einer stumpfen Nadel auf eine Masche. Ihre beiden schrägen Schenkel gehören zu einem einzigen V. Das V ist das typische Bild einer rechten Masche."]},{"nr":3,"titel":"Das Stück umdrehen","text":["Wende das Gestrick, ohne eine Masche zu stricken. Auf dieser Seite liegen kleine Querbögen und Knötchen. Hier siehst du die Rückseite derselben Maschen."]},{"nr":4,"titel":"Direkt unter die Nadel schauen","text":["Betrachte bei einer anstehenden Masche den Bereich unmittelbar unter der Nadel. Ein V zeigt eine rechte Masche; ein vorn liegender Querbogen zeigt eine linke. Schau auf die Seite, die gerade zu dir zeigt."]}],"fotoErgebnis":{"src":"assets/fotos/t04-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Suche auf der glatten Seite drei vollständige V-Maschen und zeige jeweils auf beide Schenkel. Drehe das Stück um und suche drei Querbögen. Falls du das Rippenstück aus Türchen 3 zur Hand hast, suche dort beide Formen nebeneinander."],"erkennen":["Du kannst auf der glatten Fläche eine Maschenspalte mit dem Finger nach oben verfolgen. Auf dem Rippenstück wechseln sich V-Spalten und Bereiche mit Querbögen ab. Zum Erkennen musst du keine Maschen von der Nadel nehmen."],"hakt":[{"problem":"Alles sieht gleich aus.","loesung":"Halte die Fläche locker auseinander und sorge für Licht von der Seite. Ein sehr flauschiges oder dunkles Garn verdeckt die kleinen Strukturen."},{"problem":"Die Nadel verdeckt die Form.","loesung":"Ziehe das Gestrick unterhalb der Nadel leicht nach unten. Untersuche die erste vollständige Masche darunter, statt nur die Schlinge auf der Nadel anzusehen."}],"fuerHeute":["Wenn eine Anleitung sagt „Maschen stricken, wie sie erscheinen“, hilft dir dieser Blick: Rechte Maschen strickst du rechts, linke links. Das gilt immer von der Seite aus, die du gerade ansiehst."]},{"nr":5,"titel":"Maschen sicher zählen","seite":29,"einleitung":["Eine kurze Zählpause erspart langes Suchen. Heute zählst du die lebenden Maschen direkt auf der Nadel."],"imBlick":"Eine Schlinge ist eine Masche","bereit":["Nimm ein Stück, das genau 12 Maschen haben sollte. Du brauchst keine neue Reihe zu stricken. Eine zweite stumpfe Nadel kann als Zeiger dienen."],"fotoEntdecken":{"src":"assets/fotos/t05-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t05-schritt-1.webp","w":616,"h":409,"alt":"Auf dem gleichmäßig dicken Schaft zählen"},{"src":"assets/fotos/t05-schritt-2.webp","w":616,"h":409,"alt":"Die Schlingen leicht auseinanderziehen"}],"fotosDetail":[{"src":"assets/fotos/t05-detail-1.webp","w":616,"h":409,"alt":"Eine ganze Schlinge zählt einmal"},{"src":"assets/fotos/t05-detail-2.webp","w":616,"h":409,"alt":"Zur Kontrolle erneut zählen"}],"schritte":[{"nr":1,"titel":"Auf den Schaft schieben","text":["Schiebe die Maschen vom spitzen Ende auf den gleichmäßig dicken Teil der Nadel. Dort können sie beim Zählen nicht so leicht abrutschen."]},{"nr":2,"titel":"Etwas Abstand schaffen","text":["Verteile die Schlingen locker auf dem Nadelschaft. Ziehe das Gestrick nur leicht auseinander. Jede Schlinge soll einzeln erkennbar bleiben."]},{"nr":3,"titel":"Schlinge für Schlinge zählen","text":["Berühre jede vollständige Schlinge auf der Nadel einmal mit der Zeigerspitze. Eine Schlinge zählt als eine Masche. Ihre zwei Fadenschenkel werden nicht getrennt gezählt."]},{"nr":4,"titel":"In kleinen Gruppen prüfen","text":["Zähle ein zweites Mal in Zweiergruppen. Sechs Gruppen mit je zwei Maschen ergeben 12. Auch die erste und die letzte Masche gehören zur Gesamtzahl."]}],"fotoErgebnis":{"src":"assets/fotos/t05-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Zähle dein Stück zuerst von links nach rechts. Lege es kurz hin und zähle anschließend in Zweiergruppen. Stricke eine Reihe ohne Zu- oder Abnahmen und wiederhole die Kontrolle. Zähle an deinem eigenen Stück jede vollständige Schlinge genau einmal."],"erkennen":["Beide Zählweisen liefern dasselbe Ergebnis. Bei der Übung bleibt die Zahl nach dem Stricken unverändert. Ein Fadenende oder ein später verwendeter Maschenmarkierer wird niemals als Masche mitgezählt."],"hakt":[{"problem":"Du kommst auf die doppelte Zahl.","loesung":"Du hast vermutlich beide Seiten jeder Schlinge einzeln gezählt. Verfolge eine Schlinge über die Nadel hinweg: Sie umschließt den Schaft nur einmal."},{"problem":"Du zählst 11 oder 13.","loesung":"Stricke nicht sofort weiter. Suche nach einer heruntergerutschten Masche oder einer zusätzlichen losen Schlinge. Das Zählen zeigt dir eine Abweichung, erklärt aber noch nicht ihre Ursache."}],"fuerHeute":["Gewöhne dir die kurze Kontrolle nach einer neuen Technik an. Eine Reihe zu prüfen ist überschaubarer als viele Reihen später nach der fehlenden Masche zu suchen."]},{"nr":6,"titel":"Gestrickte Reihen zählen","seite":34,"einleitung":["Maschen zählst du quer, Reihen zählst du nach oben. An einem kleinen glatt rechten Stück lässt sich der Unterschied gut sehen."],"imBlick":"In derselben Spalte bleiben","bereit":["Schlage 12 Maschen an. Stricke zehn Reihen glatt rechts: die ungeraden Reihen rechts, die geraden links. Notiere nach jeder beendeten Reihe einen Strich auf einem Zettel. Der Anschlag zählt hier nicht als Reihe."],"fotoEntdecken":{"src":"assets/fotos/t06-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t06-schritt-1.webp","w":616,"h":409,"alt":"Das Gestrick ohne Zug flachlegen"},{"src":"assets/fotos/t06-schritt-2.webp","w":616,"h":409,"alt":"In der Mitte eine Spalte wählen"}],"fotosDetail":[{"src":"assets/fotos/t06-detail-1.webp","w":616,"h":409,"alt":"Den V-Maschen nach oben folgen"},{"src":"assets/fotos/t06-detail-2.webp","w":616,"h":409,"alt":"Die Masche auf der Nadel mitzählen"}],"schritte":[{"nr":1,"titel":"Die glatte Seite nach oben legen","text":["Lege das Stück mit den V-Maschen zu dir. Lass die lebenden Maschen sicher auf der Nadel. Streiche die Fläche locker glatt, ohne sie zu dehnen."]},{"nr":2,"titel":"Eine mittlere Spalte auswählen","text":["Suche eine V-Spalte in der Mitte. Am Rand sind Maschen oft verzogen und deshalb schwerer zu zählen. Beginne direkt oberhalb der Anschlagkante."]},{"nr":3,"titel":"V für V nach oben gehen","text":["Zähle jedes vollständig gestrickte V dieser einen Spalte einmal. Wandere senkrecht nach oben. Springe nicht in die benachbarte Spalte und zähle keine einzelnen Fadenschenkel."]},{"nr":4,"titel":"Die Reihe auf der Nadel mitzählen","text":["Zähle zuletzt auch die gerade gestrickte Masche auf der Nadel: Sie gehört zur letzten gearbeiteten Reihe. Die Anschlagmasche zählt nicht. Vergleiche die Gesamtzahl mit deinen zehn Strichen."]}],"fotoErgebnis":{"src":"assets/fotos/t06-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Zähle in einer mittleren Spalte und prüfe eine zweite daneben. Beginne mit der ersten nach dem Anschlag gestrickten Masche und ende mit der Masche auf der Nadel. Beide Spalten ergeben zehn gearbeitete Reihen. Zähle die Anschlagmasche nicht mit."],"erkennen":["Beide Spalten ergeben zehn Reihen einschließlich der zuletzt gestrickten Reihe auf der Nadel. Die Anschlagmaschen bleiben ungezählt. Die nächste zu strickende Reihe wäre Reihe 11."],"hakt":[{"problem":"Du verlierst die Spalte.","loesung":"Lege eine stumpfe Nadel längs neben die ausgewählte Spalte. So behältst du die Richtung bei."},{"problem":"Du zählst am Rand weniger.","loesung":"Die Randmaschen können anders aussehen oder sich zusammenziehen. Zähle im Inneren der Fläche und prüfe, ob du das erste vollständige V über dem Anschlag erfasst hast."}],"fuerHeute":["Die Strichliste ist eine Hilfe beim Lernen. Später kannst du viele Reihenzahlen direkt im Gestrick ablesen und deine Notizen damit kontrollieren."]},{"nr":7,"titel":"Eine Masche abheben","seite":39,"einleitung":["Beim Abheben entsteht keine neue Masche. Du setzt eine vorhandene Schlinge von einer Nadel auf die andere."],"imBlick":"Die alte Schlinge wandert mit","bereit":["Nimm ein kleines Stück mit 12 Maschen. Heute hebst du genau eine Masche wie zum Linksstricken ab. Der Arbeitsfaden bleibt dabei hinter der Arbeit."],"fotoEntdecken":{"src":"assets/fotos/t07-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t07-schritt-1.webp","w":616,"h":409,"alt":"Den Arbeitsfaden hinten halten"},{"src":"assets/fotos/t07-schritt-2.webp","w":616,"h":409,"alt":"Die vorhandene Schlinge erfassen"}],"fotosDetail":[{"src":"assets/fotos/t07-detail-1.webp","w":616,"h":409,"alt":"Die Schlinge ohne neuen Faden übertragen"},{"src":"assets/fotos/t07-detail-2.webp","w":616,"h":409,"alt":"Mit der nächsten Masche weiterarbeiten"}],"schritte":[{"nr":1,"titel":"Bis zur Übungsstelle stricken","text":["Stricke drei Maschen rechts. Die nächste Masche liegt vorn auf der linken Nadel. Lass den Arbeitsfaden hinter dem Gestrick."]},{"nr":2,"titel":"Wie zum Linksstricken einstechen","text":["Führe die rechte Nadel von rechts nach links in die nächste Masche ein. Die Bewegung gleicht dem Einstechen für eine linke Masche. Hole jedoch keinen Faden."]},{"nr":3,"titel":"Die Schlinge übertragen","text":["Schiebe die ganze vorhandene Masche von der linken auf die rechte Nadel. Ihre Lage bleibt erhalten. Ziehe keine neue Schlinge durch sie hindurch."]},{"nr":4,"titel":"Mit der nächsten Masche weiterarbeiten","text":["Stricke die folgenden acht Maschen rechts. Hinter der abgehobenen Masche liegt ein kurzer Spannfaden. Lass ihn locker genug, damit er das Stück nicht zusammenzieht."]}],"fotoErgebnis":{"src":"assets/fotos/t07-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Arbeite die beschriebene Reihe einmal: drei Maschen rechts, eine Masche wie zum Linksstricken abheben, acht Maschen rechts. Wende und stricke die ganze Rückreihe links, auch die zuvor abgehobene Masche. Du musst sie nicht noch einmal abheben."],"erkennen":["Die Maschenzahl bleibt 12. In der ersten Reihe wurde die vierte Masche nur übertragen und nicht neu gestrickt. Sie kann etwas länger aussehen als ihre Nachbarn. Das ist bei dieser Übung zu erwarten."],"hakt":[{"problem":"Eine zusätzliche Schlinge liegt auf der Nadel.","loesung":"Du hast möglicherweise den Arbeitsfaden mitgenommen. Beim reinen Abheben darf keine neue Schlinge gebildet werden."},{"problem":"Die Stelle zieht sich zusammen.","loesung":"Der Faden hinter der abgehobenen Masche ist zu kurz. Verteile die Maschen auf dem Schaft, bevor du die nächste strickst, und halte den Arbeitsfaden locker."}],"fuerHeute":["„Abheben“ braucht immer eine genauere Angabe. Heute waren das: wie zum Linksstricken und mit dem Faden hinter der Arbeit. Andere Anleitungen können eine andere Fadenlage verlangen."]},{"nr":8,"titel":"Zwei Maschen zusammenstricken","seite":44,"einleitung":["Mit einer einfachen Abnahme verringerst du die Maschenzahl. Heute werden zwei benachbarte Maschen gemeinsam rechts gestrickt."],"imBlick":"Aus zwei wird eine","bereit":["Bereite ein kleines Stück mit 12 Maschen vor. Beginne eine rechte Reihe. Du arbeitest nur eine Abnahme in der Mitte und behältst dadurch einen guten Überblick."],"fotoEntdecken":{"src":"assets/fotos/t08-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t08-schritt-1.webp","w":616,"h":409,"alt":"Die beiden nächsten Maschen"},{"src":"assets/fotos/t08-schritt-2.webp","w":616,"h":409,"alt":"Beide Schlingen auf einer Nadelspitze"}],"fotosDetail":[{"src":"assets/fotos/t08-detail-1.webp","w":616,"h":409,"alt":"Die Schlingen beim Durchholen"},{"src":"assets/fotos/t08-detail-2.webp","w":616,"h":409,"alt":"Die Abnahmestelle im Detail"}],"schritte":[{"nr":1,"titel":"Die beiden Maschen vorbereiten","text":["Stricke fünf Maschen rechts. Schiebe die nächsten zwei Maschen nah an die linke Spitze. Der Arbeitsfaden liegt hinter der Arbeit."]},{"nr":2,"titel":"Durch beide Maschen einstechen","text":["Stich von vorn zuerst durch die zweite Masche von der linken Spitze aus und dann weiter durch die erste. Erfasse beide vorderen Maschenglieder gemeinsam wie zum Rechtsstricken. Beide Maschen bleiben noch links."]},{"nr":3,"titel":"Eine neue Schlinge durchholen","text":["Erfasse den Arbeitsfaden und ziehe ihn durch beide Maschen nach vorn. Es entsteht eine einzige neue Schlinge auf der rechten Nadel."]},{"nr":4,"titel":"Beide alten Maschen abgleiten lassen","text":["Lass beide alten Maschen gemeinsam von der linken Spitze gleiten. Stricke die restlichen fünf Maschen rechts. Die Reihe ist nun um eine Masche kürzer."]}],"fotoErgebnis":{"src":"assets/fotos/t08-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Arbeite einmal: fünf Maschen rechts, zwei Maschen rechts zusammen, fünf Maschen rechts. Zähle danach. Stricke die Rückreihe mit linken Maschen über die neue Gesamtzahl. Arbeite in dieser Rückreihe keine weitere Abnahme."],"erkennen":["Aus 12 Maschen sind 11 geworden: fünf einzelne Maschen, eine aus der Abnahme und fünf einzelne Maschen. Auf der glatt rechten Seite neigt sich diese Abnahme nach rechts. Die zwei ursprünglichen Spalten laufen in einer Masche zusammen."],"hakt":[{"problem":"Die Nadel geht kaum hindurch.","loesung":"Schiebe beide Maschen näher zur Spitze und entspanne den Faden. Versuche nicht, die Nadel mit Kraft durch zu enge Schlingen zu drücken."},{"problem":"Du hast weiter 12 Maschen.","loesung":"Prüfe, ob du tatsächlich beide Maschen gemeinsam gestrickt hast. Wenn nur eine erfasst wurde, fand noch keine Abnahme statt."}],"fuerHeute":["In vielen Anleitungen steht dafür „2 M re zusstr“. Dahinter steckt genau die Bewegung von heute: zwei vorhandene Maschen ergeben eine neue."]},{"nr":9,"titel":"Einen Umschlag arbeiten","seite":49,"einleitung":["Ein Umschlag legt eine neue Schlinge auf die Nadel. Dabei wird keine vorhandene Masche abgestrickt. Das kleine Loch darunter ist heute erwünscht."],"imBlick":"Eine zusätzliche Schlinge","bereit":["Nimm ein Stück mit 12 Maschen. Du arbeitest einen Umschlag zwischen zwei rechten Maschen. Diese Übung enthält keine ausgleichende Abnahme."],"fotoEntdecken":{"src":"assets/fotos/t09-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t09-schritt-1.webp","w":616,"h":409,"alt":"Vor dem Umschlag"},{"src":"assets/fotos/t09-schritt-2.webp","w":616,"h":409,"alt":"Der Faden über der rechten Nadel"}],"fotosDetail":[{"src":"assets/fotos/t09-detail-1.webp","w":616,"h":409,"alt":"Die zusätzliche Schlinge"},{"src":"assets/fotos/t09-detail-2.webp","w":616,"h":409,"alt":"Der Umschlag neben den Maschen"}],"schritte":[{"nr":1,"titel":"Bis zur Mitte stricken","text":["Stricke sechs Maschen rechts. Der Arbeitsfaden liegt hinter der Arbeit. Die übrigen sechs Maschen warten auf der linken Nadel."]},{"nr":2,"titel":"Den Faden nach vorn holen","text":["Führe den Arbeitsfaden zwischen den Nadelspitzen nach vorn. Bis hierhin kennst du die Bewegung aus Türchen 3."]},{"nr":3,"titel":"Über die rechte Nadel legen","text":["Führe den Faden jetzt über die rechte Nadel nach hinten. Eine zusätzliche Schlinge liegt auf dem Nadelschaft. Für diese Schlinge wurde keine Masche der linken Nadel verbraucht."]},{"nr":4,"titel":"Die nächste Masche rechts stricken","text":["Stricke die nächste Masche normal rechts und anschließend die restlichen Maschen. Achte darauf, dass der Umschlag als eigene Schlinge auf der rechten Nadel liegen bleibt."]}],"fotoErgebnis":{"src":"assets/fotos/t09-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Arbeite: sechs Maschen rechts, ein Umschlag, sechs Maschen rechts. Zähle anschließend 13 Maschen. Wende und stricke alle 13 Maschen links. Stich beim Umschlag normal wie zum Linksstricken ein, ohne seine Schenkel zu verdrehen."],"erkennen":["Der einzelne Umschlag hat die Zahl von 12 auf 13 erhöht. Nach der Rückreihe bleibt unter ihm ein kleines Loch sichtbar. Ein Umschlag wird beim Zählen als eine Masche behandelt, obwohl er zunächst kein V aus einer alten Masche unter sich hat."],"hakt":[{"problem":"Es sind zwei zusätzliche Schlingen.","loesung":"Der Faden wurde vermutlich zweimal um die Nadel gelegt. Heute brauchst du nur eine vollständige neue Schlinge."},{"problem":"Das Loch ist kaum zu sehen.","loesung":"Prüfe, ob du den Umschlag in der Rückreihe verdreht abgestrickt hast. Eine verschränkte Verarbeitung verändert das Ergebnis. Für diese Übung soll der Umschlag offen bleiben."}],"fuerHeute":["Der Unterschied zu Türchen 3 ist bewusst: Dort wanderte der Faden nur zwischen den Spitzen. Heute kommt der Weg über die rechte Nadel hinzu."]},{"nr":10,"titel":"Einen Maschenmarkierer setzen","seite":54,"einleitung":["Ein kleiner Ring kann dir eine Stelle merken. Er liegt zwischen zwei Maschen und wird beim Stricken nur weitergereicht."],"imBlick":"Die Markierung mitnehmen","bereit":["Du brauchst ein Stück mit 12 Maschen und einen geschlossenen Ringmarkierer, der locker über die Nadeln passt. Heute markierst du eine Stelle nach der dritten Masche. Verwende einen glatten Ring ohne scharfe Kanten."],"fotoEntdecken":{"src":"assets/fotos/t10-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t10-schritt-1.webp","w":616,"h":409,"alt":"Den Ring bereitlegen"},{"src":"assets/fotos/t10-schritt-2.webp","w":616,"h":409,"alt":"Den Ring an die Nadelspitze führen"}],"fotosDetail":[{"src":"assets/fotos/t10-detail-1.webp","w":616,"h":409,"alt":"Die Markierung zwischen den Maschen"},{"src":"assets/fotos/t10-detail-2.webp","w":616,"h":409,"alt":"Den Ring auf die rechte Nadel nehmen"}],"schritte":[{"nr":1,"titel":"Die Stelle erreichen","text":["Stricke drei Maschen rechts. Halte den Ringmarkierer bereit. Er soll auf den Nadelschaft und nicht durch eine Garnschlinge gesteckt werden."]},{"nr":2,"titel":"Den Ring aufsetzen","text":["Schiebe den Ring über die Spitze der rechten Nadel. Er liegt jetzt hinter der Spitze und direkt neben den drei bereits gestrickten Maschen."]},{"nr":3,"titel":"Die Reihe fertigstricken","text":["Stricke die restlichen neun Maschen rechts. Der Ring liegt zwischen der dritten und der vierten Masche der ursprünglichen Reihe. Er zählt nicht als Masche."]},{"nr":4,"titel":"In der Rückreihe übertragen","text":["Wende und stricke neun Maschen rechts. Wenn du den Ring erreichst, schiebe ihn von der linken auf die rechte Nadel. Stricke danach die übrigen drei Maschen rechts."]}],"fotoErgebnis":{"src":"assets/fotos/t10-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Setze den Ring nur einmal in der ersten Hinreihe ein. Arbeite danach die Rückreihe und noch eine Hin- und Rückreihe. Wenn du den Ring erreichst, überträgst du ihn ohne Fadenumschlag auf die rechte Nadel. Füge keinen zweiten Ring hinzu."],"erkennen":["Du zählst weiterhin 12 Maschen und zusätzlich einen Ring. Von der einen Kante aus sind es drei Maschen bis zur Markierung, von der anderen neun. Der Ring bleibt zwischen denselben Maschenspalten."],"hakt":[{"problem":"Du willst den Ring abstricken.","loesung":"Halte vor ihm kurz an und setze ihn einfach um. Er ist ein Orientierungspunkt und gehört nicht zum Garn."},{"problem":"Die Markierung sitzt im Gestrick fest.","loesung":"Ein Ringmarkierer wird auf die Nadel geschoben. Zum Einhängen in eine gestrickte Masche braucht man dagegen einen verschließbaren Markierer; das ist eine andere Anwendung."}],"fuerHeute":["In späteren Anleitungen kann der Ring einen Musterabschnitt oder eine Abnahmestelle markieren. Nimm ihn wieder ab, sobald du ihn nicht mehr brauchst."]},{"nr":11,"titel":"Maschen locker abketten","seite":59,"einleitung":["Beim Abketten schließt du die offenen Maschen nacheinander. Heute übst du die einfache rechts gestrickte Variante."],"imBlick":"Eine ruhige Abschlusskante","bereit":["Nimm ein kleines kraus rechtes Übungsstück mit 12 Maschen. Lege eine Schere bereit. Der Arbeitsfaden bleibt am Knäuel, bis nur noch eine Schlinge übrig ist."],"fotoEntdecken":{"src":"assets/fotos/t11-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t11-schritt-1.webp","w":616,"h":409,"alt":"Zwei Maschen auf der rechten Nadel"},{"src":"assets/fotos/t11-schritt-2.webp","w":616,"h":409,"alt":"Die Nadelspitzen an der Abkettstelle"}],"fotosDetail":[{"src":"assets/fotos/t11-detail-1.webp","w":616,"h":409,"alt":"Die jüngere Masche sicher halten"},{"src":"assets/fotos/t11-detail-2.webp","w":616,"h":409,"alt":"Die Schlingen locker auf dem Schaft"}],"schritte":[{"nr":1,"titel":"Zwei Maschen rechts stricken","text":["Stricke die ersten beiden Maschen rechts. Auf der rechten Nadel liegen jetzt zwei neue Maschen. Halte sie auf dem gleichmäßig dicken Schaft locker."]},{"nr":2,"titel":"Die ältere Masche anheben","text":["Stich mit der linken Nadelspitze in die zuerst gestrickte der beiden Maschen auf der rechten Nadel. Sie liegt weiter von deren Spitze entfernt. Hebe diese ältere Masche an."]},{"nr":3,"titel":"Über die jüngere Masche ziehen","text":["Hebe die ältere Masche über die jüngere und über die rechte Nadelspitze hinweg. Die jüngere Masche bleibt auf der rechten Nadel; ziehe den Arbeitsfaden dabei nicht fest."]},{"nr":4,"titel":"Mit einer weiteren Masche fortfahren","text":["Stricke die nächste Masche der linken Nadel rechts. Jetzt liegen wieder zwei Maschen rechts. Hebe erneut die ältere über die jüngere. Wiederhole, bis links keine Masche mehr liegt."]}],"fotoErgebnis":{"src":"assets/fotos/t11-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Kette die Reihe vollständig ab. Wenn nur noch eine Schlinge auf der rechten Nadel liegt, schneide den Arbeitsfaden mit etwa 15 cm Rest ab. Ziehe dieses Fadenende vollständig durch die letzte Schlinge und lege den Abschluss vorsichtig an."],"erkennen":["Die offenen Maschen sind geschlossen. Am oberen Rand liegt eine kleine Kette. Der Abschluss sollte die Breite des lockeren Übungsstücks nicht sichtbar zusammenziehen. Für sehr dehnbare Bündchen kann später eine elastischere Abkettmethode nötig sein."],"hakt":[{"problem":"Die Kante zieht sich zusammen.","loesung":"Die übergehobenen Maschen waren zu eng. Arbeite die Schlingen auf dem Nadelschaft, nicht nur auf den dünnen Spitzen, und halte den Arbeitsfaden lockerer."},{"problem":"Die jüngere Masche rutscht mit herunter.","loesung":"Halte sie mit der rechten Nadel sicher fest, während du nur die ältere überhebst. Es bleibt nach jedem Überheben genau eine Masche auf der rechten Nadel."}],"fuerHeute":["Bewahre das kleine Stück samt Fadenenden auf. Im nächsten Türchen gibst du ihm den letzten sauberen Abschluss."]},{"nr":12,"titel":"Ein Fadenende vernähen","seite":64,"einleitung":["Heute bekommt ein kleines Übungsstück seinen Abschluss. Du führst das Fadenende auf der Rückseite durch mehrere Maschenbögen."],"imBlick":"Den Faden im Gestrick sichern","bereit":["Nimm ein abgekettetes kraus rechtes Stück mit einem etwa 15 cm langen Fadenende, eine stumpfe Wollnadel und eine Schere. Verwende zum Üben ein normales Wollgarn. Ein Faden in Kontrastfarbe macht den Vernähweg in den Bildern gut erkennbar."],"fotoEntdecken":{"src":"assets/fotos/t12-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t12-schritt-1.webp","w":616,"h":409,"alt":"Das Fadenende einfädeln"},{"src":"assets/fotos/t12-schritt-2.webp","w":616,"h":409,"alt":"Die Wollnadel unter die Bögen führen"}],"fotosDetail":[{"src":"assets/fotos/t12-detail-1.webp","w":616,"h":409,"alt":"Der Fadenweg unter den Maschenbögen"},{"src":"assets/fotos/t12-detail-2.webp","w":616,"h":409,"alt":"Flachlegen und die Spannung prüfen"}],"schritte":[{"nr":1,"titel":"Das Ende einfädeln","text":["Fädle das Fadenende in die stumpfe Wollnadel. Lege die gewählte Rückseite des Stücks nach oben. Bei kraus rechtem Gestrick sehen beide Seiten ähnlich aus; bleibe für das Vernähen auf einer Seite."]},{"nr":2,"titel":"Durch mehrere Bögen führen","text":["Führe die Wollnadel nahe am Rand unter die rückseitigen Maschenbögen. Folge ihrem Verlauf seitwärts über zwei benachbarte Reihen, statt gerade durch die Fläche zu stechen. Ziehe den Faden locker nach; auf der Vorderseite darf die Nadel nicht austreten."]},{"nr":3,"titel":"Die Richtung wechseln","text":["Führe den Faden unter benachbarten Bögen einige Zentimeter zurück. Wähle einen leicht versetzten Weg, statt den ersten Weg rückwärts wieder aufzulösen. Der Faden soll innerhalb der Maschenstruktur verlaufen."]},{"nr":4,"titel":"Glattstreichen und kontrollieren","text":["Ziehe das Stück sanft in Breite und Länge. Der Faden darf keine Falte bilden. Prüfe die Vorderseite. Erst wenn alles flach liegt und das Ende sicher hält, schneidest du den überstehenden Rest vorsichtig ab."]}],"fotoErgebnis":{"src":"assets/fotos/t12-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Vernähe zuerst nur ein Ende und lass den Rest noch ungekürzt. Bewege das Stück vorsichtig auseinander und wieder zusammen. Kontrolliere, ob sich der Faden herauszieht oder sichtbar wird. Vernähe anschließend das zweite Ende."],"erkennen":["Die Fläche bleibt weich und liegt flach. Auf der Vorderseite ist kein auffälliger Vernähweg zu sehen. Nach dem sanften Dehnen hält das Ende weiterhin. Ein dicker Knoten ist für diese Übung nicht nötig."],"hakt":[{"problem":"Die Fläche kräuselt sich.","loesung":"Du hast den Faden zu straff nachgezogen. Lockere den Weg vorsichtig mit der stumpfen Nadel und verteile die Weite wieder."},{"problem":"Das Ende rutscht heraus.","loesung":"Führe es durch weitere Bögen und wechsle noch einmal versetzt die Richtung. Sehr glatte Garne benötigen eine darauf abgestimmte Sicherung; prüfe ihre Pflege- und Verarbeitungshinweise."}],"fuerHeute":["Zwölf Türchen liegen hinter dir. Bewahre ein kleines fertiges Stück als Vergleich auf. Morgen widmest du dich der seitlichen Kante."]},{"nr":13,"titel":"Einen Kettenrand arbeiten","seite":69,"einleitung":["Ein regelmäßiger Seitenrand beginnt schon mit der ersten Masche. Bei dieser Variante hebst du sie in jeder Reihe ab; die letzte Masche strickst du rechts."],"imBlick":"Die erste Masche gleitet nur mit","bereit":["Nimm ein Stück mit 12 Maschen. Die beiden Randmaschen sind in diesen 12 enthalten. Dazwischen liegen zehn Maschen. Du strickst in Hin- und Rückreihen."],"fotoEntdecken":{"src":"assets/fotos/t13-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t13-schritt-1.webp","w":616,"h":409,"alt":"Die erste Randmasche"},{"src":"assets/fotos/t13-schritt-2.webp","w":616,"h":409,"alt":"Die vorhandene Schlinge erfassen"}],"fotosDetail":[{"src":"assets/fotos/t13-detail-1.webp","w":616,"h":409,"alt":"Krausrippen zwischen den Rändern"},{"src":"assets/fotos/t13-detail-2.webp","w":616,"h":409,"alt":"Die nächste Randmasche auf der Nadel"}],"schritte":[{"nr":1,"titel":"Den Faden nach vorn legen","text":["Zu Beginn der Reihe liegt die volle Nadel links. Führe den Arbeitsfaden vor die Arbeit, ohne ihn um die Nadel zu wickeln."]},{"nr":2,"titel":"Die erste Masche abheben","text":["Stich wie zum Linksstricken von rechts nach links ein. Übertrage die erste Masche unverändert auf die rechte Nadel. Du holst keinen neuen Faden."]},{"nr":3,"titel":"Die Mitte rechts stricken","text":["Führe den Faden zwischen den Spitzen nach hinten. Stricke die folgenden zehn Maschen rechts. Die abgehobene Randmasche bleibt locker auf dem Schaft."]},{"nr":4,"titel":"Mit einer rechten Masche enden","text":["Stricke auch die letzte Masche rechts. Wende und beginne die nächste Reihe wieder mit Faden vorn und einer wie zum Linksstricken abgehobenen Masche."]}],"fotoErgebnis":{"src":"assets/fotos/t13-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Arbeite sechs Reihen nach dieser Folge: eine Masche abheben mit Faden vorn, zehn Maschen rechts, eine Masche rechts. Schaue nach jeder zweiten Reihe auf beide Seitenkanten."],"erkennen":["Die Gesamtzahl bleibt 12. Am Rand entstehen längliche Kettenglieder. Ein solches Randglied erstreckt sich über zwei Reihen; seine Form unterscheidet sich deshalb von den kleineren Maschen in der Fläche."],"hakt":[{"problem":"Neben dem Rand ist ein Loch.","loesung":"Prüfe, ob beim Wechsel nach hinten ein zusätzlicher Umschlag entstanden ist. Der Faden läuft zwischen den Spitzen hindurch."},{"problem":"Die Kante zieht sich zusammen.","loesung":"Ziehe die zweite Masche nicht kräftig fest. Der Randfaden muss zwei Reihen überbrücken können."}],"fuerHeute":["Diese Randvariante ist eine bewusste Wahl. Übernimm bei einem anderen Projekt stets die dort angegebene Randmasche."]},{"nr":14,"titel":"Eine schmale Blende stricken","seite":74,"einleitung":["Eine kraus rechte Blende rahmt eine glatt rechte Fläche ein. Du brauchst dafür keine zweite Nadelstärke und keine zusätzliche Naht."],"imBlick":"Zwei Randmaschen auf jeder Seite","bereit":["Schlage 12 Maschen an. Die ersten und letzten zwei Maschen bilden die Blenden; acht Maschen liegen in der Mitte. Reihe 1 ist die Hinreihe."],"fotoEntdecken":{"src":"assets/fotos/t14-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t14-schritt-1.webp","w":616,"h":409,"alt":"Die Hinreihe auf der Nadel"},{"src":"assets/fotos/t14-schritt-2.webp","w":616,"h":409,"alt":"Der Faden an den Randmaschen"}],"fotosDetail":[{"src":"assets/fotos/t14-detail-1.webp","w":616,"h":409,"alt":"Glatte Mitte und krauser Rand"},{"src":"assets/fotos/t14-detail-2.webp","w":616,"h":409,"alt":"Die Randmaschen in Nahaufnahme"}],"schritte":[{"nr":1,"titel":"Die Hinreihe rechts arbeiten","text":["Stricke in Reihe 1 alle 12 Maschen rechts. Damit sind die beiden Blenden und die Mitte zunächst gleich gearbeitet."]},{"nr":2,"titel":"Die Rückreihe beginnen","text":["Wende. Stricke die ersten zwei Maschen rechts. Führe den Arbeitsfaden danach zwischen den Spitzen nach vorn."]},{"nr":3,"titel":"Die Mitte links stricken","text":["Stricke die nächsten acht Maschen links. Auf der linken Nadel bleiben jetzt noch genau zwei Maschen übrig."]},{"nr":4,"titel":"Die zweite Blende abschließen","text":["Führe den Faden zwischen den Spitzen nach hinten. Stricke die letzten zwei Maschen rechts. Wende und beginne wieder mit einer vollständig rechten Hinreihe."]}],"fotoErgebnis":{"src":"assets/fotos/t14-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Wiederhole die beiden Reihen viermal, insgesamt acht Reihen: Hinreihe 12 rechts; Rückreihe 2 rechts, 8 links, 2 rechts. Hier wird keine Randmasche abgehoben."],"erkennen":["Du zählst 12 Maschen. Die Mitte zeigt auf der Vorderseite V-Spalten. Die jeweils zwei äußeren Maschen bilden Querrippen. Ein so schmaler Rand kann das Einrollen mindern, verhindert es aber nicht bei jedem Garn vollständig."],"hakt":[{"problem":"Die Blende sieht glatt aus.","loesung":"Wahrscheinlich hast du die äußeren Maschen in der Rückreihe ebenfalls links gestrickt. Beide Blenden werden in jeder Reihe rechts gearbeitet."},{"problem":"Die Mitte hat eine Querrippe.","loesung":"Prüfe deine Rückreihe: Die acht mittleren Maschen werden dort links gestrickt. Ein Reihenstrich auf Papier hilft beim Wechsel."}],"fuerHeute":["Das Prinzip lässt sich später auf breitere Blenden übertragen. Die Mitte und die beiden Ränder behalten jeweils ihre eigene Reihenfolge."]},{"nr":15,"titel":"Kleines Perlmuster stricken","seite":79,"einleitung":["Aus denselben zwei Maschenarten entsteht eine körnige Fläche. Der Unterschied zum Rippenmuster liegt im Wechsel von Reihe zu Reihe."],"imBlick":"Rechts und links versetzen","bereit":["Schlage 12 Maschen an. Du arbeitest über alle Maschen; zusätzliche Randmaschen gibt es in dieser Übung nicht. Reihe 1 beginnt rechts."],"fotoEntdecken":{"src":"assets/fotos/t15-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t15-schritt-1.webp","w":616,"h":409,"alt":"Das Muster nach den ersten Reihen"},{"src":"assets/fotos/t15-schritt-2.webp","w":616,"h":409,"alt":"Rechte und linke Maschen wechseln"}],"fotosDetail":[{"src":"assets/fotos/t15-detail-1.webp","w":616,"h":409,"alt":"Die versetzten Körnchen"},{"src":"assets/fotos/t15-detail-2.webp","w":616,"h":409,"alt":"Die Maschen auf der Nadel"}],"schritte":[{"nr":1,"titel":"Die erste Reihe stricken","text":["Wiederhole sechsmal: eine Masche rechts, eine Masche links. Die zwölfte und letzte Masche ist links. Wende die Arbeit."]},{"nr":2,"titel":"Die zweite Reihe links beginnen","text":["Stricke die erste Masche jetzt links. Sie erscheint dir vor dem Stricken als rechte Masche. Genau dieser Gegensatz ist gewollt."]},{"nr":3,"titel":"Den Wechsel fortsetzen","text":["Wiederhole in Reihe 2 sechsmal: eine Masche links, eine Masche rechts. Die letzte Masche dieser Reihe ist rechts. Führe den Faden bei jedem Wechsel zwischen den Spitzen."]},{"nr":4,"titel":"Die beiden Reihen wiederholen","text":["Reihe 3 entspricht Reihe 1, Reihe 4 entspricht Reihe 2. Stricke rechte Maschen über erscheinenden linken und linke über erscheinenden rechten Maschen."]}],"fotoErgebnis":{"src":"assets/fotos/t15-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Arbeite sechs Reihen: ungerade Reihen sechsmal 1 rechts, 1 links; gerade Reihen sechsmal 1 links, 1 rechts. Zähle nach jeder Reihe die 12 Maschen."],"erkennen":["Kleine Erhebungen stehen versetzt nebeneinander. Es entstehen keine durchgehenden rechten Rippen. Beide Seiten zeigen eine ähnliche körnige Struktur."],"hakt":[{"problem":"Es entstehen schmale Rippen.","loesung":"Du hast vermutlich jede Reihe mit derselben Maschenart begonnen. Bei dieser geraden Maschenzahl wechselst du den Reihenanfang: rechts, links, rechts, links."},{"problem":"Du weißt nicht, welche Reihe folgt.","loesung":"Betrachte die erste Masche, wie sie vor dir erscheint. Für das Perlmuster strickst du die entgegengesetzte Maschenart; Türchen 4 hilft beim Erkennen."}],"fuerHeute":["Vergleiche das Ergebnis mit Türchen 3. Eine kleine Änderung im Reihenbeginn verändert das ganze Muster."]},{"nr":16,"titel":"Ein Schachbrettmuster stricken","seite":84,"einleitung":["Heute wachsen die einzelnen Perlen zu kleinen Feldern. Jedes Feld ist zwei Maschen breit und zwei Reihen hoch."],"imBlick":"Nach zwei Reihen die Felder wechseln","bereit":["Schlage 12 Maschen an. Das ergibt drei Wiederholungen aus je vier Maschen. Reihe 1 ist die Hinreihe. Die Randmaschen gehören vollständig zum Muster."],"fotoEntdecken":{"src":"assets/fotos/t16-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t16-schritt-1.webp","w":616,"h":409,"alt":"Glatte und bogenförmige Maschen"},{"src":"assets/fotos/t16-schritt-2.webp","w":616,"h":409,"alt":"Die kleinen Felder nebeneinander"}],"fotosDetail":[{"src":"assets/fotos/t16-detail-1.webp","w":616,"h":409,"alt":"Der Wechsel nach zwei Reihen"},{"src":"assets/fotos/t16-detail-2.webp","w":616,"h":409,"alt":"Die wiederholte Musterfläche"}],"schritte":[{"nr":1,"titel":"Zwei Maschen rechts, zwei links","text":["Stricke in Reihe 1 dreimal die Folge: zwei Maschen rechts, zwei Maschen links. Wende erst, wenn alle 12 Maschen gearbeitet sind."]},{"nr":2,"titel":"Die zweite Reihe genauso arbeiten","text":["Stricke auch Reihe 2 dreimal: zwei rechts, zwei links. Durch das Wenden liegen die gleichen Maschenarten auf der Vorderseite übereinander."]},{"nr":3,"titel":"In Reihe 3 die Felder tauschen","text":["Beginne jetzt mit zwei linken Maschen. Wiederhole dreimal: zwei links, zwei rechts. Wende und arbeite Reihe 4 genau wie Reihe 3."]},{"nr":4,"titel":"Den Viererblock wiederholen","text":["Nach Reihe 4 beginnst du wieder bei Reihe 1. Notiere jede fertige Reihe, damit der Wechsel immer nach zwei Reihen erfolgt."]}],"fotoErgebnis":{"src":"assets/fotos/t16-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Stricke acht Reihen, also zwei vollständige Viererblöcke. Reihen 1, 2, 5 und 6: dreimal 2 rechts, 2 links. Reihen 3, 4, 7 und 8: dreimal 2 links, 2 rechts."],"erkennen":["Die Zahl bleibt 12. Auf der Vorderseite wechseln glatte und körnige Felder. Nach jeweils zwei Reihen wechseln sie ihren Platz. Vergleiche die glatten und die bogenförmigen Stellen auf der Vorderseite."],"hakt":[{"problem":"Die Felder werden lange Streifen.","loesung":"Der Wechsel nach zwei Reihen fehlt. Markiere die Reihen 2, 4, 6 und 8 auf deinem Zettel als Wechselpunkte."},{"problem":"Die Felder sind unterschiedlich breit.","loesung":"Zähle in Zweiergruppen. Ein zu früher Fadenwechsel verschiebt die Grenze um eine Masche."}],"fuerHeute":["Bewahre die Reihenfolge auf: Zwei gleiche Arbeitsreihen bilden hier eine Ebene von Feldern."]},{"nr":17,"titel":"Am Rand die Farbe wechseln","seite":89,"einleitung":["Ein Farbwechsel am Reihenanfang braucht keinen dicken Verbindungsknoten. Die offenen Enden werden später einzeln im Gestrick gesichert."],"imBlick":"Mit dem neuen Faden beginnen","bereit":["Bereite mit Farbe A ein kraus rechtes Stück mit 12 Maschen und mindestens vier Reihen vor. Lege Farbe B in gleicher Garnstärke bereit. Beide Garne sollten dieselben Pflegeanforderungen haben."],"fotoEntdecken":{"src":"assets/fotos/t17-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t17-schritt-1.webp","w":616,"h":409,"alt":"Der Reihenanfang vor dem Farbwechsel"},{"src":"assets/fotos/t17-schritt-2.webp","w":616,"h":409,"alt":"Den neuen Arbeitsfaden bereithalten"}],"fotosDetail":[{"src":"assets/fotos/t17-detail-1.webp","w":616,"h":409,"alt":"Die erste Masche mit der neuen Farbe"},{"src":"assets/fotos/t17-detail-2.webp","w":616,"h":409,"alt":"Die neue Farbe über die ganze Reihe"}],"schritte":[{"nr":1,"titel":"Den alten Faden ablegen","text":["Beende eine Reihe vollständig. Schneide Farbe A mit etwa 15 cm Rest ab. Wende. Die volle Nadel liegt links; Farbe B ist noch nicht an der Arbeit befestigt."]},{"nr":2,"titel":"Den neuen Faden bereitlegen","text":["Lass auch bei Farbe B etwa 15 cm Anfangsfaden frei. Führe nur den langen, zum Knäuel laufenden Teil über den linken Zeigefinger und hinter die Arbeit."]},{"nr":3,"titel":"Die erste Masche neu stricken","text":["Stich in die erste Masche wie zum Rechtsstricken ein. Hole eine Schlinge aus Farbe B durch sie hindurch. Halte den kurzen Anfangsfaden mit der anderen Hand am Rand fest, damit er nicht nachrutscht."]},{"nr":4,"titel":"Mit einer Farbe weiterarbeiten","text":["Stricke die restlichen elf Maschen mit Farbe B rechts. Der kurze Anfangsfaden wird nicht mitgestrickt. Arbeite die Rückreihe ebenfalls rechts und lege die erste Masche behutsam an."]}],"fotoErgebnis":{"src":"assets/fotos/t17-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Stricke insgesamt vier Reihen mit Farbe B. Vernähe danach beide Enden des Farbwechsels getrennt auf derselben Rückseite, wie in Türchen 12. Ziehe dabei die Seitenkante nicht zusammen."],"erkennen":["Auf der Nadel liegen 12 Maschen in Farbe B. An der Kante hängen zunächst zwei getrennte Enden. Beim kraus rechten Farbwechsel ist auf einer Seite eine Reihe mit gemischten Farbbögen sichtbar; das gehört zur Struktur."],"hakt":[{"problem":"Die erste Masche wird riesig.","loesung":"Halte das kurze Ende während der ersten Maschen fest. Lege die Schlinge später durch einen sanften Zug an diesem Ende an."},{"problem":"Es liegen doppelte Schlingen auf der Nadel.","loesung":"Prüfe, ob du Anfangs- und Arbeitsfaden gemeinsam benutzt hast. In dieser Übung wird nur der zum Knäuel führende Faden gestrickt."}],"fuerHeute":["Wähle für die sichtbare Seite bewusst die ruhigere Farbkante. Auch die Rückseite darf ordentlich aussehen."]},{"nr":18,"titel":"Eine offene Masche sichern","seite":94,"einleitung":["Eine heruntergerutschte Masche muss nicht weiterlaufen. Heute fängst du die offene Schlinge auf; das Hochholen folgt im nächsten Türchen."],"imBlick":"Erst auffangen, dann reparieren","bereit":["Nimm ein glatt rechtes Stück mit 12 Maschen und mindestens acht Reihen. Lege einen verschließbaren Maschenmarkierer und eine passende Häkelnadel bereit. Für die Übung reicht eine einzige verlorene Reihe."],"fotoEntdecken":{"src":"assets/fotos/t18-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t18-schritt-1.webp","w":616,"h":409,"alt":"Die lose Garnschlinge offen halten"},{"src":"assets/fotos/t18-schritt-2.webp","w":616,"h":409,"alt":"Den verschließbaren Markierer öffnen"}],"fotosDetail":[{"src":"assets/fotos/t18-detail-1.webp","w":616,"h":409,"alt":"Durch die Öffnung der Schlinge führen"},{"src":"assets/fotos/t18-detail-2.webp","w":616,"h":409,"alt":"Den Markierer vollständig schließen"}],"schritte":[{"nr":1,"titel":"Eine Übungsmasche freilegen","text":["Beginne eine rechte Reihe und stricke fünf Maschen rechts. Schiebe die nächste Masche vorsichtig von der linken Spitze, während du die Schlinge mit den Fingern festhältst. Sichere die übrigen Maschen auf den Nadeln."]},{"nr":2,"titel":"Nur eine Reihe lösen","text":["Lockere diese eine Schlinge behutsam, bis sie sich auflöst. Halte die darunter frei werdende Schlinge sofort fest. Direkt darüber liegt nun ein loser Querfaden. Ziehe nicht am Gestrick."]},{"nr":3,"titel":"Den Markierer einhängen","text":["Öffne den verschließbaren Markierer. Führe ihn durch die ganze offene Schlinge, ohne einen Fadenschenkel zu teilen. Alternativ hält die Häkelnadel die Schlinge vorübergehend."]},{"nr":4,"titel":"Die Schlinge sicher ablegen","text":["Schließe den Markierer vollständig. Lass den Querfaden darüber frei. Lege beide Stricknadeln so ab, dass die elf übrigen Maschen nicht abrutschen."]}],"fotoErgebnis":{"src":"assets/fotos/t18-ergebnis.webp","w":616,"h":409,"alt":"Die ganze Garnschlinge ist im geschlossenen Markierer gesichert."},"uebung":["Sichere genau eine offene Schlinge. Lass sie bis Türchen 19 am Markierer. Wenn du heute nicht absichtlich eine Masche lösen möchtest, kannst du das Einhängen auch an einer einzelnen losen Garnschlinge üben."],"erkennen":["Bei der Übung am Gestrick liegen elf Maschen auf den beiden Nadeln und eine offene Schlinge im Markierer. Darüber befindet sich genau ein loser Querfaden. Alle zwölf Maschenspalten sind damit noch vorhanden."],"hakt":[{"problem":"Die Schlinge läuft weiter nach unten.","loesung":"Halte sofort an und fange die jetzt unterste offene Schlinge mit der Häkelnadel auf. Ziehe die Fläche nicht auseinander."},{"problem":"Der Markierer steckt nur im Faden.","loesung":"Er muss durch die Öffnung der ganzen Schlinge laufen. Durchstochene Garnfasern sichern die Masche nicht zuverlässig."}],"fuerHeute":["Ein geschlossener Ring aus Türchen 10 eignet sich hierfür nicht. Du brauchst einen Markierer, den du öffnen und schließen kannst."]},{"nr":19,"titel":"Eine rechte Masche hochholen","seite":99,"einleitung":["Aus einer gesicherten Schlinge und ihrem Querfaden wird wieder eine vollständige Masche. Arbeite von der glatt rechten Seite aus."],"imBlick":"Den Querfaden durch die Schlinge ziehen","bereit":["Verwende die Übung aus Türchen 18: fünf Maschen rechts gestrickt, eine Masche um eine Reihe gefallen, sechs Maschen noch links. Eine Häkelnadel sollte bequem durch die offene Schlinge passen."],"fotoEntdecken":{"src":"assets/fotos/t19-entdecken.webp","w":503,"h":501,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t19-schritt-1.webp","w":339,"h":339,"alt":"Die Öffnung mit dem Haken erfassen"},{"src":"assets/fotos/t19-schritt-2.webp","w":340,"h":339,"alt":"Den einzelnen Querfaden beachten"}],"fotosDetail":[{"src":"assets/fotos/t19-detail-1.webp","w":339,"h":339,"alt":"Die Schlinge am Haken"},{"src":"assets/fotos/t19-detail-2.webp","w":340,"h":339,"alt":"Die Stricknadel übernimmt die Schlinge"}],"schritte":[{"nr":1,"titel":"Die offene Schlinge aufnehmen","text":["Stich mit der Häkelnadel von vorn nach hinten durch die gesicherte Schlinge. Erst wenn sie auf der Häkelnadel liegt, öffnest und entfernst du den Markierer."]},{"nr":2,"titel":"Den Querfaden erfassen","text":["Der lose Querfaden liegt hinter der Häkelnadel, unmittelbar oberhalb der Schlinge. Hole ihn mit dem Haken. Bei mehreren Querfäden beginnt man immer mit dem untersten."]},{"nr":3,"titel":"Eine neue Schlinge bilden","text":["Ziehe den erfassten Querfaden durch die alte Schlinge nach vorn. Die alte Schlinge gleitet vom Haken, die neue bleibt darauf. Damit ist eine verlorene Reihe wiederhergestellt."]},{"nr":4,"titel":"Zurück auf die Stricknadel setzen","text":["Setze die neue Schlinge an die Spitze der linken Nadel, vor die sechs wartenden Maschen. Ihr rechtes Maschenglied liegt vorn. Stricke sie rechts und danach die restlichen sechs Maschen."]}],"fotoErgebnis":{"src":"assets/fotos/t19-ergebnis.webp","w":503,"h":501,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Beende die rechte Reihe und zähle alle Maschen. Stricke die Rückreihe über 12 Maschen links. Bei einer tiefer gefallenen Masche würdest du vor dem Zurücksetzen jeden weiteren Querfaden einzeln von unten nach oben durchholen."],"erkennen":["Die Reihe enthält wieder 12 Maschen. An der Reparaturstelle liegt kein loser Querfaden mehr. Die gerettete Masche bildet eine offene V-Form, keine gekreuzten Fadenschenkel."],"hakt":[{"problem":"Unter der neuen Masche bleibt ein Loch.","loesung":"Möglicherweise hast du einen Querfaden übersprungen. Sichere die Schlinge, bevor du den betreffenden Abschnitt erneut öffnest."},{"problem":"Die reparierte Masche ist verdreht.","loesung":"Prüfe ihre Lage auf der linken Nadel, bevor du sie strickst. Setze sie bei Bedarf um, sodass das rechte Maschenglied vorn liegt."}],"fuerHeute":["Diese Übung gilt für eine rechte Maschenspalte in glatt rechtem Gestrick. Kraus rechts und Musterflächen brauchen eine an die jeweilige Reihe angepasste Reparatur."]},{"nr":20,"titel":"Einen Rettungsfaden einziehen","seite":104,"einleitung":["Ein dünner Hilfsfaden kann eine korrekt gestrickte Reihe sichern. Die Stricknadeln bleiben dabei in der Arbeit; darüber strickst du normal weiter."],"imBlick":"Eine richtige Reihe festhalten","bereit":["Nimm ein fehlerfreies Stück mit 12 Maschen am Ende einer Reihe. Du brauchst eine stumpfe Wollnadel und etwa 40 cm glatten, farblich abgesetzten Hilfsfaden, dünner als das Strickgarn."],"fotoEntdecken":{"src":"assets/fotos/t20-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t20-schritt-1.webp","w":616,"h":409,"alt":"Die Maschen auf der Nadel zugänglich machen"},{"src":"assets/fotos/t20-schritt-2.webp","w":616,"h":409,"alt":"Den Hilfsfaden neben der Nadel einziehen"}],"fotosDetail":[{"src":"assets/fotos/t20-detail-1.webp","w":616,"h":409,"alt":"Jede Masche muss gesichert sein"},{"src":"assets/fotos/t20-detail-2.webp","w":616,"h":409,"alt":"Über dem Rettungsfaden weiterstricken"}],"schritte":[{"nr":1,"titel":"Die Maschen zugänglich machen","text":["Schiebe alle Maschen auf den Schaft oder das Seil der Rundstricknadel. Verteile sie locker. Notiere, welche Reihe gerade beendet wurde."]},{"nr":2,"titel":"Den Hilfsfaden einziehen","text":["Fädle ihn in die Wollnadel. Führe die Wollnadel wie zum Linksstricken durch jede der zwölf Schlingen, jeweils neben der Stricknadel. Die Maschen bleiben dabei auf der Stricknadel."]},{"nr":3,"titel":"Alle Schlingen prüfen","text":["Verfolge den Faden von einer Kante zur anderen. Er muss durch alle zwölf Maschen laufen. Umgehe Ringmarkierer; sie werden nicht auf den Hilfsfaden gefädelt. Lass an beiden Seiten lange Enden frei."]},{"nr":4,"titel":"Über der Sicherung weiterstricken","text":["Verknote die beiden Enden des Hilfsfadens locker miteinander, mit genügend Spiel für die Breite. Stricke die nächste Reihe nur aus dem eigentlichen Strickgarn. Der Hilfsfaden bleibt darunter liegen."]}],"fotoErgebnis":{"src":"assets/fotos/t20-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Arbeite nach dem Einziehen zwei Reihen im bisherigen Muster. Prüfe, ob der Rettungsfaden weiterhin in derselben älteren Reihe verläuft. Öffne dann seinen Knoten und ziehe ihn vorsichtig seitlich heraus, wenn du ihn nicht mehr benötigst."],"erkennen":["Die Maschenzahl bleibt 12. Der Hilfsfaden sichert eine ältere Reihe und wandert nicht mit nach oben. Er lässt sich später herausziehen, ohne eine gestrickte Masche aufzulösen."],"hakt":[{"problem":"Der Hilfsfaden steigt mit auf.","loesung":"Du hast ihn zusammen mit dem Arbeitsfaden gestrickt oder durchstochen. Trenne die beiden Fäden beim Weiterstricken deutlich."},{"problem":"Eine Schlinge wurde übersprungen.","loesung":"Ziehe den Hilfsfaden zurück bis vor die Lücke und fädle ihn erneut durch die fehlende und alle folgenden Maschen."}],"fuerHeute":["Ein Rettungsfaden ist besonders vor einer neuen Musterfolge hilfreich. Er sichert den Stand der Arbeit; einen bereits vorhandenen Fehler beseitigt er nicht."]},{"nr":21,"titel":"Maschen auf einen Faden legen","seite":109,"einleitung":["Manchmal wird die Nadel für ein anderes Stück gebraucht. Auf einem glatten Hilfsfaden bleiben offene Maschen erhalten und lassen sich später wieder aufnehmen."],"imBlick":"Die Nadeln für eine Pause freimachen","bereit":["Bereite 12 Maschen am Reihenende vor. Du brauchst eine stumpfe Wollnadel und etwa 40 cm glatten Hilfsfaden in Kontrastfarbe. Der Faden sollte gut durch die Maschen passen."],"fotoEntdecken":{"src":"assets/fotos/t21-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t21-schritt-1.webp","w":616,"h":409,"alt":"Wollnadel und Hilfsfaden in der Schlinge"},{"src":"assets/fotos/t21-schritt-2.webp","w":616,"h":409,"alt":"Die gesicherten Maschen ohne Stricknadel"}],"fotosDetail":[{"src":"assets/fotos/t21-detail-1.webp","w":616,"h":409,"alt":"Die Schlingen auf dem Hilfsfaden prüfen"},{"src":"assets/fotos/t21-detail-2.webp","w":616,"h":409,"alt":"Die Stricknadel wieder einführen"}],"schritte":[{"nr":1,"titel":"Die erste Schlinge erfassen","text":["Fädle den Hilfsfaden ein. Stich mit der Wollnadel wie zum Linksstricken durch die erste Masche. Ziehe den Hilfsfaden hindurch, mit etwa 15 cm freiem Anfang."]},{"nr":2,"titel":"Erst sichern, dann abgleiten lassen","text":["Lass diese Masche erst von der Stricknadel gleiten, wenn der Hilfsfaden vollständig durch sie läuft. Wiederhole das bei jeder folgenden Masche."]},{"nr":3,"titel":"Die Enden verbinden","text":["Zähle zwölf Schlingen auf dem Hilfsfaden. Verknote dessen beide Enden miteinander, ohne die Maschen zusammenzuziehen. Der Arbeitsfaden wird nicht in diesen Knoten eingebunden."]},{"nr":4,"titel":"Die Maschen wieder aufnehmen","text":["Öffne später den Knoten. Führe eine Stricknadel entlang des Hilfsfadens durch die Maschen, ohne Fasern zu teilen. Lass den Hilfsfaden liegen, bis alle zwölf sicher auf der Nadel sind."]}],"fotoErgebnis":{"src":"assets/fotos/t21-ergebnis.webp","w":616,"h":409,"alt":"Stillgelegte Maschen bleiben auf dem Hilfsfaden erhalten."},"uebung":["Lege alle zwölf Maschen still und nimm sie anschließend wieder auf. Richte die Nadel zum Weiterstricken so aus, dass der Arbeitsfaden an der ersten zu strickenden Masche liegt. Prüfe die Lage jeder Masche: rechtes Maschenglied vorn. Ziehe dann den Hilfsfaden heraus."],"erkennen":["Die Zahl ist vor dem Stilllegen und nach dem Aufnehmen jeweils 12. Es gibt keine offene, ungesicherte Schlinge. Du kannst am bisherigen Reihenanfang weiterarbeiten."],"hakt":[{"problem":"Eine Masche ist sehr eng.","loesung":"Ziehe die restlichen Schlingen nicht am Hilfsfaden zusammen. Zum Wiederaufnehmen kann eine dünnere Stricknadel helfen; gestrickt wird danach wieder mit der passenden Stärke."},{"problem":"Eine Schlinge bleibt neben der Nadel.","loesung":"Lass den Hilfsfaden unbedingt liegen. Nimm die übersehene Masche ebenfalls auf und zähle erneut, bevor du ihn entfernst."}],"fuerHeute":["Im Unterschied zu Türchen 20 verlässt das ganze Stück heute die Stricknadel. Der Hilfsfaden übernimmt vorübergehend ihre Aufgabe."]},{"nr":22,"titel":"Eine Maschenprobe messen","seite":114,"einleitung":["Eine Maschenprobe verbindet deine Strickweise mit einem Maß. Heute misst du in der ruhigen Mitte der Fläche und lässt die unregelmäßigen Ränder außen vor."],"imBlick":"Zehn Zentimeter in der Mitte","bereit":["Du brauchst ein glatt rechtes Probestück, das nach dem Waschen und Trocknen deutlich größer als 10 × 10 cm ist; etwa 15 × 15 cm sind ein guter Anfang. Nimm ein Lineal mit Zentimeterskala. Die Pflege zeigt Türchen 23."],"fotoEntdecken":{"src":"assets/fotos/t22-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t22-schritt-1.webp","w":616,"h":409,"alt":"Die trockene Probe flachlegen"},{"src":"assets/fotos/t22-schritt-2.webp","w":426,"h":284,"alt":"In der Mitte waagerecht messen"}],"fotosDetail":[{"src":"assets/fotos/t22-detail-1.webp","w":426,"h":284,"alt":"In einer Spalte senkrecht messen"},{"src":"assets/fotos/t22-detail-2.webp","w":616,"h":409,"alt":"Beide Werte aufschreiben"}],"schritte":[{"nr":1,"titel":"Die Fläche entspannt hinlegen","text":["Lege das vollständig trockene Stück glatt auf den Tisch. Ziehe es nicht in Form, während du misst. Die glatte Seite zeigt nach oben."]},{"nr":2,"titel":"Waagerecht messen","text":["Lege die Nullmarke an die Grenze zwischen zwei mittleren Maschenspalten. Zähle über genau 10 cm jede ganze V-Masche einmal. Notiere auch einen erkennbaren Maschenanteil am Ende."]},{"nr":3,"titel":"Senkrecht messen","text":["Lege die Nullmarke an eine Reihengrenze in der Mitte. Zähle in einer Spalte über 10 cm, einschließlich eines erkennbaren Reihenanteils am Ende. Rand, Anschlag und Abkettkante bleiben außerhalb des Messbereichs."]},{"nr":4,"titel":"Das Ergebnis notieren","text":["Schreibe Garn, Nadelstärke und beide Werte auf: zum Beispiel 20 Maschen und 28 Reihen auf 10 × 10 cm. Das sind Beispielwerte, kein Soll für dein Garn."]}],"fotoErgebnis":{"src":"assets/fotos/t22-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Miss ein zweites Mal an einer benachbarten Stelle. Liegen die Werte weit auseinander, glätte das Stück ohne Zug und prüfe erneut. Für die spätere Passform vergleichst du deine Werte mit der konkreten Projektanleitung."],"erkennen":["Dein Ergebnis enthält eine Maschenzahl für die Breite und eine Reihenzahl für die Höhe, beide bezogen auf 10 cm. Die genannten Werte sind Beispiele; an deinem eigenen Probestück kann das Ergebnis anders sein."],"hakt":[{"problem":"Am Rand kommt eine andere Zahl heraus.","loesung":"Randmaschen sind oft breiter oder schmaler. Verlege den Messbereich in die Mitte einer ausreichend großen Probe."},{"problem":"Das Projekt würde zu klein werden.","loesung":"Mehr Maschen auf 10 cm als angegeben bedeuten kleinere Maschen. Eine größere Nadel kann helfen; weniger Maschen auf 10 cm sprechen für eine kleinere. Fertige mit der geänderten Stärke eine neue Probe an."}],"fuerHeute":["Bewahre die Probe mit ihren Angaben auf. Damit kannst du später nachvollziehen, welches Ergebnis genau diese Kombination aus Garn und Nadeln hatte."]},{"nr":23,"titel":"Das Gestrick in Form legen","seite":119,"einleitung":["Die letzte Form entsteht häufig erst nach der Pflege. Eine kleine Probe zeigt dir, wie dein Garn darauf reagiert, bevor ein größeres Projekt fertig ist."],"imBlick":"Wasser ausdrücken und flach trocknen","bereit":["Nimm ein abgekettetes Probestück, dessen Garn laut Banderole mit Wasser gewaschen werden darf. Notiere vor dem Waschen Breite und Höhe. Beachte Temperatur und Waschweise auf der Banderole. Lege passende Waschlösung, Handtuch und eine ebene Trockenfläche bereit."],"fotoEntdecken":{"src":"assets/fotos/t23-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t23-schritt-1.webp","w":616,"h":409,"alt":"Die Probe behutsam waschen"},{"src":"assets/fotos/t23-schritt-2.webp","w":616,"h":409,"alt":"Wasser vorsichtig ausdrücken"}],"fotosDetail":[{"src":"assets/fotos/t23-detail-1.webp","w":616,"h":409,"alt":"Restwasser im Handtuch aufnehmen"},{"src":"assets/fotos/t23-detail-2.webp","w":616,"h":409,"alt":"Flach in Form trocknen lassen"}],"schritte":[{"nr":1,"titel":"Behutsam waschen","text":["Wasche oder benetze die Probe entsprechend den Garnangaben. Bewege sie vorsichtig. Reibe und knete Wollgestrick nicht kräftig; spüle nach Vorgabe des verwendeten Waschmittels."]},{"nr":2,"titel":"Das Wasser herausdrücken","text":["Hebe das Stück mit beiden Händen gestützt heraus. Drücke Wasser sanft aus, ohne es zu verdrehen. Lass die nasse Probe nicht an einer Ecke herunterhängen."]},{"nr":3,"titel":"Im Handtuch ausdrücken","text":["Lege sie flach auf das Handtuch, schlage das Tuch darüber und rolle beides locker auf. Drücke auf die Rolle. Öffne sie wieder und nimm das feuchte Stück heraus."]},{"nr":4,"titel":"Flach trocknen lassen","text":["Lege die Probe auf eine trockene, luftige Unterlage. Richte Kanten und Maschenspalten mit den Fingern aus, ohne die Fläche kräftig zu dehnen. Lass sie vollständig trocknen."]}],"fotoErgebnis":{"src":"assets/fotos/t23-ergebnis.webp","w":616,"h":409,"alt":"Ergebnisansicht · Größe und Maschenzahl richten sich nach deiner Übung."},"uebung":["Miss Breite und Höhe vor der Pflege und nach dem vollständigen Trocknen. Notiere eine Veränderung. Bei der Maschenprobe aus Türchen 22 zählen die Werte des trockenen, gepflegten Stücks."],"erkennen":["Die Maschen liegen entspannt und die Kanten sind gleichmäßig ausgerichtet. Das Garn darf sein eigenes Maß annehmen. Für diese kleine Probe brauchst du weder Bügeleisen noch eine mit Nadeln erzwungene Größe."],"hakt":[{"problem":"Das Stück wird beim Anheben länger.","loesung":"Nasses Gestrick kann schwer sein. Unterstütze es vollständig und lege es vorsichtig wieder flach."},{"problem":"Es ist innen noch feucht.","loesung":"Warte mit Messen und Verstauen. Wechsle eine feuchte Unterlage und ermögliche Luftzirkulation; starke Hitze ist kein Ersatz für die passende Garnpflege."}],"fuerHeute":["Du musst die Probe heute nicht fertig trocknen sehen. Lege sie in Ruhe ab und miss erst, wenn sie wirklich trocken ist."]},{"nr":24,"titel":"Eine kleine Strickschleife formen","seite":124,"einleitung":["Zum letzten Türchen wird aus einem schlichten Rechteck eine kleine Schleife. Die Mitte entsteht durch Falten und Umwickeln, ganz ohne neue Maschenart."],"imBlick":"Das Rechteck bekommt eine Mitte","bereit":["Bereite ein kraus rechtes Rechteck vor, etwa 10 × 5 cm. Bestimme die Anschlagzahl für 10 cm an einer kraus rechten Probe aus demselben Garn mit denselben Nadeln. Stricke bis 5 cm Höhe, kette locker ab und vernähe die Enden. Dazu etwa 50 cm Garn und eine Wollnadel."],"fotoEntdecken":{"src":"assets/fotos/t24-entdecken.webp","w":616,"h":409,"alt":""},"fotosSchritt":[{"src":"assets/fotos/t24-schritt-1.webp","w":616,"h":409,"alt":"Die Mitte des Rechtecks finden"},{"src":"assets/fotos/t24-schritt-2.webp","w":616,"h":409,"alt":"Die Mitte zusammendrücken"}],"fotosDetail":[{"src":"assets/fotos/t24-detail-1.webp","w":616,"h":409,"alt":"Die Mitte mit Garn umwickeln"},{"src":"assets/fotos/t24-detail-2.webp","w":616,"h":409,"alt":"Die Wicklung auf der Rückseite sichern"}],"schritte":[{"nr":1,"titel":"Die Mitte finden","text":["Lege das Rechteck mit der langen Kante waagerecht vor dich. Falte es kurz von links nach rechts zusammen, um die Mitte zu finden, und öffne es wieder."]},{"nr":2,"titel":"Die Mitte zusammendrücken","text":["Raffe das Gestrick in der Mitte von oben nach unten zu zwei oder drei kleinen Ziehharmonikafalten. Halte die schmale Mitte zwischen Daumen und Zeigefinger. Die Seiten fächern sich auf."]},{"nr":3,"titel":"Die Mitte umwickeln","text":["Lege den extra Garnfaden um die geraffte Mitte. Lass etwa 15 cm Anfang frei und wickle den langen Teil drei- bis fünfmal darum. Ziehe so weit an, dass die Falten zusammenhalten, ohne das Garn einzuschneiden."]},{"nr":4,"titel":"Hinten befestigen","text":["Verknote Anfang und Ende auf der Rückseite mit einem Doppelknoten. Fädle jedes Ende in die Wollnadel und führe es auf der Rückseite unter mehreren Wicklungen hindurch. Kürze erst, wenn die Wicklung sicher sitzt."]}],"fotoErgebnis":{"src":"assets/fotos/t24-ergebnis.webp","w":616,"h":409,"alt":"Die geraffte und umwickelte Mitte formt die Schleife."},"uebung":["Zupfe beide Schleifenseiten gleichmäßig zurecht. Zum Befestigen an einem Geschenk kannst du ein separates Band durch die rückseitige Wicklung führen. Die Schleife lässt sich so später wieder abnehmen."],"erkennen":["Die Wicklung sitzt in der Mitte und verrutscht bei vorsichtigem Bewegen nicht. Die beiden Seiten sind etwa gleich groß. Das Foto zeigt eine Gestaltungsanregung; Größe und Falten hängen von deinem Rechteck ab."],"hakt":[{"problem":"Eine Seite ist deutlich größer.","loesung":"Löse die Wicklung vor dem endgültigen Sichern und verschiebe sie zur tatsächlichen Mitte des Rechtecks."},{"problem":"Die Mitte wird sehr dick.","loesung":"Forme weniger Falten und wickle nur so oft wie nötig. Ein dickeres Garn benötigt häufig weniger Wicklungen."}],"fuerHeute":["Vielleicht schmückt die Schleife ein Geschenk, vielleicht bleibt sie an deinem Wollkorb. Sie trägt etwas von diesen vierundzwanzig kleinen Strickmomenten mit sich."]}],"rahmen":{"aufbau":{"label":"SO IST JEDES TÜRCHEN AUFGEBAUT","titel":"Vier Seiten, ein Handgriff","einleitung":["Jedes Türchen hat vier Seiten, und auf jeder Seite siehst du ein Foto. Hier am Beispiel von Türchen 10, dem Maschenmarkierer."],"abschnitte":[{"h":"Entdecken","p":["Worum es heute geht, in einem Bild. Du siehst, was nachher auf deiner Nadel liegt, bevor du anfängst."]},{"h":"Schritt für Schritt","p":["Die Bewegung in Einzelbildern. Du siehst, wo die Nadel einsticht und wie die Hände den Faden halten."]},{"h":"Im Detail","p":["Nah heran. Du siehst, wie der Faden liegt und welche Schlinge gemeint ist."]},{"h":"Ausprobieren","p":["Das Ergebnis. Lege dein Stück daneben und vergleiche die Struktur. Darunter steht, woran du erkennst, dass es stimmt, und was du tust, wenn etwas hakt.","Alle Fotos zeigen helles, glattes Garn. Darin ist jede Masche zu erkennen. Maschenzahl und Größe richten sich nach deiner Übung, nicht nach dem Foto."]}]},"willkommen":{"label":"WILLKOMMEN","titel":"Ein bisschen Zeit für deine Maschen","einleitung":["Vielleicht liegen deine Nadeln ohnehin jeden Abend bereit. Vielleicht wartet ein angefangenes Stück seit Wochen im Korb. Im Advent darfst du dir einen einzelnen Handgriff vornehmen und in Ruhe betrachten, was dabei geschieht. Jeder Handgriff ist in Fotos gezeigt, Schritt für Schritt und nah: Du siehst, wo die Nadel einsticht, wie der Faden liegt und wie das Ergebnis aussehen soll.","Hinter jedem Türchen steckt eine kleine Technik: eine neue Schlinge bilden, einen Faden führen, ein Muster erkennen oder eine offene Masche retten. Du arbeitest mit überschaubaren Proben. Daraus muss kein großes Projekt werden."],"abschnitte":[{"h":"Ein Kalender in deinem Tempo","p":["Manche Türchen dauern wenige Minuten. Andere brauchen ein vorbereitetes Stück oder eine Trockenpause. Die Vorbereitung steht immer dabei. Du darfst ein Türchen auf mehrere Tage verteilen oder eine bekannte Bewegung nur nachschlagen."]},{"h":"Was du mitbringst","p":["Du kannst Maschen anschlagen und ein kleines Strickstück halten. Rechte und linke Maschen werden zum Auffrischen ausführlich erklärt. Die Übungen sind in Reihen gearbeitet; am Reihenende wird gewendet."]},{"h":"Was am Ende bleibt","p":["Du hast kleine Muster und Kanten kennengelernt, Maschen gezählt und einfache Fehler eingegrenzt. Das letzte Türchen macht aus einem vorbereiteten Rechteck eine Strickschleife. Ein Spickzettel und eine schnelle Fehlerübersicht begleiten dich auch nach Weihnachten.","Lege dir einen Garnrest bereit. Für den Anfang genügen zwölf Maschen."]}]},"material":{"label":"DEIN ÜBUNGSPLATZ","titel":"Wenig Material, gut sichtbare Maschen","einleitung":[],"abschnitte":[{"h":"Garn und Nadeln","p":["Nimm glattes, einfarbiges Garn in einer hellen oder mittleren Farbe. Für die ersten Übungen ist ein normales Wollgarn praktisch; sehr flauschiges, dunkles oder unregelmäßiges Garn verdeckt die Maschen. Reste genügen. Eine zweite Farbe in ähnlicher Stärke kommt ab Türchen 17 hinzu.","Verwende passende Stricknadeln nach der Garnbanderole, beispielsweise 4 bis 5 mm. Bei einer Rundstricknadel arbeitest du hier ebenfalls hin und zurück, ohne zur Runde zu schließen."]},{"h":"Kleines Zubehör","p":["Lege eine stumpfe Wollnadel, eine Schere, ein Lineal mit Zentimeterskala sowie Papier und Stift bereit. Dazu kommen ein geschlossener Ringmarkierer, ein verschließbarer Maschenmarkierer und eine Häkelnadel, die durch deine Schlingen passt.","Für Türchen 20 und 21 brauchst du glatten, dünneren Hilfsfaden in Kontrastfarbe. Für Türchen 23 genügen passende Waschlösung, Handtuch und eine ebene Trockenfläche. Die Pflegeangaben des Garns sind maßgeblich."]},{"h":"Zwei Arten von Markierern","p":["Ein Ring auf der Nadel markiert eine Stelle. Ein verschließbarer Markierer kann zusätzlich eine offene Schlinge sichern. Lege beide griffbereit in eine kleine Schale."]}],"fotos":[{"src":"assets/fotos/vorab-material-1.webp","w":346,"h":230,"alt":"Glattes, helles Garn und Nadeln in 4 bis 5 mm. Mehr brauchst du für den Anfang nicht."},{"src":"assets/fotos/vorab-material-2.webp","w":393,"h":262,"alt":"Der Ring sitzt auf der Nadel und markiert eine Stelle (Türchen 10)."},{"src":"assets/fotos/vorab-material-3.webp","w":346,"h":230,"alt":"Der verschließbare Markierer hält eine offene Schlinge fest (Türchen 18)."}]},"lesen":{"label":"SO LIEST DU DIE ANLEITUNGEN","titel":"Faden, Masche und Blickrichtung","einleitung":[],"abschnitte":[{"h":"Die Ausgangslage","p":["Die volle Nadel liegt in der linken Hand. Die rechte Nadel arbeitet die nächste Masche. Der Arbeitsfaden läuft zum Knäuel; das kurze Anschlagende bleibt unbenutzt. Beschrieben wird die kontinentale Fadenhaltung über den linken Zeigefinger."]},{"h":"Vorn und hinten","p":["„Vorn“ bedeutet auf der dir zugewandten Seite des Gestricks, „hinten“ auf der von dir abgewandten. Das ist nicht automatisch die spätere Vorder- oder Rückseite des fertigen Stücks."]},{"h":"Normal liegende Maschen","p":["Bei den hier verwendeten Maschen liegt das rechte Maschenglied vorn auf der linken Nadel. „Wie zum Linksstricken abheben“ bedeutet, die Schlinge von rechts nach links zu erfassen und ohne neue Schlinge zu übertragen."]},{"h":"So nutzt du die Fotos","p":["Wie die vier Seiten eines Türchens zusammenspielen, zeigt Seite 2. Arbeite immer die beschriebene Maschen- und Reihenzahl an deinem eigenen Stück; die Fotos zeigen unterschiedlich große Ausschnitte."]},{"h":"Reihen und Ränder","p":["Alle Maschenzahlen enthalten die erste und letzte Masche. Zusätzliche Randmaschen werden nicht stillschweigend ergänzt. Die Anschlagmaschen zählen hier nicht als gestrickte Reihe. Abkürzungen sind auf Seite 130 gesammelt."]}],"fotos":[{"src":"assets/fotos/vorab-ausgangslage.webp","w":900,"h":250,"alt":"So liegt die Arbeit auf allen Fotos: Die Maschen warten links, die rechte Nadel arbeitet, der Arbeitsfaden kommt von rechts. Du schaust von oben auf die Nadelspitzen."}]},"proben":{"label":"DIE KLEINEN PROBEN","titel":"Du brauchst nicht 24 neue Strickstücke","einleitung":[],"abschnitte":[{"h":"Für den Anfang","p":["Ein Stück mit 12 Maschen reicht für viele Grundlagen. Du kannst nach Türchen 1 mit linken Maschen weiterarbeiten und anschließend einen neuen Musterabschnitt beginnen. Für die Zählübungen ist eine übersichtliche, gleichmäßige Fläche hilfreich."]},{"h":"Wenn die Maschenzahl sich ändert","p":["Türchen 8 endet mit 11 Maschen, Türchen 9 mit 13. Für spätere Übungen mit 12 Maschen beginne eine neue kleine Probe oder kehre an deinem Übungsstück zur Ausgangsstelle zurück. Die jeweilige Vorbereitung ist verbindlich."]},{"h":"Abschluss und neue Muster","p":["Für Türchen 11 und 12 brauchst du ein kraus rechtes Stück zum Abketten und Vernähen. Die Rand- und Musterübungen 13–16 können als getrennte Abschnitte auf einer weiteren Probe entstehen. Notiere den Beginn jedes Abschnitts."]},{"h":"Reparaturen gehören zusammen","p":["Türchen 18 sichert eine offene Masche. Türchen 19 holt genau diese Masche wieder hoch. Verwende dafür eine kleine glatt rechte Probe, an der eine einzelne Maschenspalte gut zu erkennen ist."]},{"h":"Zwei Vorbereitungen zum Schluss","p":["Für Türchen 22 muss die Probe deutlich größer als 10 × 10 cm sein. Pflege sie nach Türchen 23 und miss erst im trockenen Zustand. Für Türchen 24 brauchst du ein fertiges kraus rechtes Rechteck, ungefähr doppelt so breit wie hoch.","Ein kleiner Zettel am Stück genügt: Maschenzahl, Muster und zuletzt gearbeitete Reihe. So findest du nach einer Pause leichter zurück."]}],"fotos":[{"src":"assets/fotos/vorab-proben-1.webp","w":614,"h":409,"alt":"Das Übungsstück: 12 Maschen, kraus rechts (Türchen 1)."},{"src":"assets/fotos/vorab-proben-2.webp","w":330,"h":220,"alt":"Für Türchen 24: ein kraus rechtes Rechteck, etwa doppelt so breit wie hoch."}]},"abschluss":{"label":"NACH DEM LETZTEN TÜRCHEN","titel":"Was du mitnimmst","einleitung":["Vierundzwanzig kleine Strickmomente liegen hinter dir. Manche Bewegung war schnell vertraut, bei einer anderen hast du vielleicht länger hingesehen. Beides gehört dazu. Ein einzelner Handgriff kann bereits verändern, wie ruhig und sicher du weiterarbeitest."],"abschnitte":[{"h":"Die Proben behalten","p":["Wähle zwei oder drei Stücke aus, an denen du etwas gut erkennst: den sauberen Rand, die gerettete Masche oder den Unterschied zwischen Rippen- und Perlmuster. Eine Notiz mit Garn und Nadelstärke macht aus einem Rest ein nützliches Musterstück."]},{"h":"Einen Kniff mitnehmen","p":["Vielleicht setzt du künftig häufiger einen Markierer. Vielleicht zählst du Reihen in der Mitte oder lässt beim Farbwechsel längere Enden stehen. Du brauchst nicht alles gleichzeitig zu ändern. Nimm die Technik mit, die dir bei deiner nächsten Arbeit tatsächlich hilft.","Eine kleine Schleife aus kraus rechtem Gestrick kann auch nach dem Advent noch ein Geschenk schmücken."]}]},"spickzettel":{"label":"DEIN SPICKZETTEL","titel":"Die wichtigsten Griffe","einleitung":[],"abschnitte":[{"h":"Rechts · re","p":["Faden hinten. Vorn einstechen, neue Schlinge nach vorn holen, alte Masche lösen. Türchen 1 · Seite 10."]},{"h":"Links · li","p":["Faden vorn. Von rechts nach links einstechen, neue Schlinge nach hinten holen. Türchen 2 · Seite 15."]},{"h":"Fadenwechsel","p":["Für rechts und links: zwischen den Spitzen hindurch. Für einen Umschlag kommt der Weg über die Nadel hinzu. Türchen 3 und 9 · Seiten 20 und 50."]},{"h":"Abheben · abh.","p":["Eine vorhandene Schlinge übertragen, ohne neu zu stricken. Abheberichtung und Fadenlage beachten. Türchen 7 · Seite 40."]},{"h":"Abnahme · 2 M re zusstr","p":["Zwei Maschen rechts zusammenstricken: Die Zahl sinkt um eine. Türchen 8 · Seite 45."]},{"h":"Umschlag · U","p":["Eine zusätzliche Schlinge ohne alte Masche bilden: Die Zahl steigt um eine. Türchen 9 · Seite 50."]},{"h":"Zählen · M und R","p":["M = Masche, R = Reihe. Eine Schlinge zählt einmal. Beim Reihenzählen zählt die zuletzt gestrickte Reihe auf der Nadel mit, der Anschlag nicht. Türchen 5 und 6 · Seiten 30 und 35."]},{"h":"Glatt rechts / kraus rechts","p":["In Reihen: glatt rechts = Hinreihe rechts, Rückreihe links. Kraus rechts = jede Reihe rechts. Ohne zusätzliche Randregel werden alle Maschen mitgearbeitet."]}]},"hilfe":{"label":"SCHNELLE HILFE","titel":"Wo du nachschlagen kannst","einleitung":[],"abschnitte":[{"h":"Eine Masche zu viel","p":["Prüfe den Fadenweg und suche einen unbeabsichtigten Umschlag. Türchen 3 und 9 · Seiten 20 und 50."]},{"h":"Eine Masche fehlt","p":["Zähle zuerst alle Schlingen. Suche nach einer Abnahme oder offenen Masche. Türchen 5, 8 und 18 · Seiten 30, 45 und 95."]},{"h":"Eine offene Schlinge rutscht","p":["Sichere sie mit einem verschließbaren Markierer. Das Hochholen einer rechten Masche folgt in Türchen 19 · Seite 100."]},{"h":"Die Kante wird eng","p":["Kontrolliere Randfaden und Abkettschlingen. Türchen 11 und 13 · Seiten 60 und 70."]},{"h":"Das Muster stimmt nicht","p":["Vergleiche erscheinende Maschen und Reihenfolge. Türchen 4, 15 und 16 · Seiten 25, 80 und 85."]},{"h":"Ein Fadenende löst sich","p":["Prüfe den Vernähweg und die Eignung für dein Garn. Türchen 12 · Seite 65."]},{"h":"Die Nadel wird gebraucht","p":["Lege die Maschen gesichert auf einen Hilfsfaden. Türchen 21 · Seite 110."]},{"h":"Die Größe passt nicht","p":["Miss die trockene, gepflegte Probe in der Mitte. Türchen 22 und 23 · Seiten 115 und 120."]}]},"quellen":[{"titel":"DMC · Stricktechniken Schritt für Schritt","links":["dmc.com/DE/de/sbs-knitting-stitch-diagrams"]},{"titel":"Lion Brand · The Ups and Downs of Knitting: Counting Your Rows","links":["lionbrand.com/community/blog/the-ups-and-downs-of-knitting-counting-your-rows/"]},{"titel":"Craft Yarn Council · Knitwise or Purlwise; Bind off","links":["media.craftyarncouncil.com/read_instructions.html","media.craftyarncouncil.com/files/teach/WUA-PTG_Bk_web_5.pdf"]},{"titel":"The Knitting Guild Association · Yarn Overs in Creating Lace","links":["tkga.org · Cast On, Spring 2023, Debbie West"]},{"titel":"DROPS Design · Maschen abnehmen; verlorene Maschen auffangen","links":["garnstudio.com/lesson.php?cid=9&id=6","garnstudio.com/lesson.php?cid=9&id=10"]},{"titel":"DROPS Design · Fäden vernähen bei kraus rechts","links":["garnstudio.com/video.php?id=250&lang=de"]},{"titel":"Knit Picks · How to Use a Lifeline for Lace Knitting","links":["tutorials.knitpicks.com/how-to-use-a-lifeline-for-lace-knitting/"]},{"titel":"Knit Picks · Knit Stitch Continental; Purl Stitch Continental","links":["tutorials.knitpicks.com/knit-stitch-continental/","tutorials.knitpicks.com/purl-stitch-continental/"]},{"titel":"addi · Randmasche stricken lernen","links":["addi.de/story/randmasche-stricken/"]},{"titel":"Purl Soho · All About Gauge","links":["purlsoho.com/create/all-about-gauge/"]}]}};
